select s.id,t.id,'drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-67','Repertório CEBRASPE — Direito Constitucional',2017,'Agente de Polícia Federal', 'CEBRASPE','Direito Constitucional','Direitos e garantias fundamentais','Acerca dos direitos e das garantias fundamentais previstos na Constituição Federal de 1988 (CF), julgue o item a seguir. No Estado brasileiro, é plena a liberdade de associação de seus cidadãos, desde que para fins lícitos, sendo expressamente vedado qualquer tipo de associação de caráter paramilitar.','C','Associações lícitas são livres; as de caráter paramilitar são vedadas. Origem declarada pela coletânea: CEBRASPE (CESPE) - Of (CBM AL)/CBM AL/Combatente/2017. Item 67 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual antes da publicação.','[{"norma":"Constituição Federal","artigo":"5º, XVII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}]'::jsonb,'média','under_review',false,'2026-09-30T00:00:00-03:00'::timestamptz
